import sys
input = sys.stdin.readline

n = int(input().rstrip())
arr = list(map(int, input().rstrip().split()))

res = 0
first_occurrence = {}

for i in range(2 * n):
    color = arr[i]
    if color in first_occurrence:
        if i - first_occurrence[color] == 2:
            res += 1
    else:
        first_occurrence[color] = i

print(res)
